<?php $rows=$pdo->query('SELECT id,full_name,email,role,status,created_at FROM users ORDER BY full_name')->fetchAll();layout_start('Staff accounts','users'); ?><div class="page-heading"><div><p class="eyebrow">ADMINISTRATION</p><h1>Staff accounts</h1><p class="muted">Manage who can access the CareShare workspace.</p></div><a class="button primary" href="?page=user-form">＋ Add staff member</a></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['full_name'])?></td><td><?=h($r['email'])?></td><td><?=h($r['role'])?></td><td><span class="badge <?=strtolower($r['status'])?>"><?=h($r['status'])?></span></td><td><?=date('j M Y',strtotime($r['created_at']))?></td><td><a class="text-link" href="?page=user-form&id=<?=$r['id']?>">Edit →</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php layout_end();
